content:
{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 16,
      "text_ar": "الويل لك يا بابل ويا آسيا! الويل لك يا مصر ويا سوريا!",
      "verse": 1
    },
    {
      "chapter": 16,
      "text_ar": "البسوا المسوح وثياب شعر المعزى، واندموا على أولادكم وנוحووا؛ فإن هلاككم قريب.",
      "verse": 2
    },
    {
      "chapter": 16,
      "text_ar": "أرسل عليكم سيف، ومن ذا الذي يردُّه؟",
      "verse": 3
    },
    {
      "chapter": 16,
      "text_ar": "أرسلت عليكم نار، ومن ذا الذي يطفئها؟",
      "verse": 4
    },
    {
      "chapter": 16,
      "text_ar": "أرسلت عليكم بليات، ومن ذا الذي يطردها؟",
      "verse": 5
    },
    {
      "chapter": 16,
      "text_ar": "أيمكن لأحد أن يطرد أسداً جائعاً في الغابة؟ أو يطفئ ناراً في القش متى اشتعلت؟",
      "verse": 6
    },
    {
      "chapter": 16,
      "text_ar": "أيمكن لأحد أن يردَّ سهماً أطلقه رامي قوي؟",
      "verse": 7
    },
    {
      "chapter": 16,
      "text_ar": "الرب الإله يرسل البليات، ومن ذا الذي يطردها؟",
      "verse": 8
    },
    {
      "chapter": 16,
      "text_ar": "ستخرج نار من غضبه، ومن ذا الذي يطفئها؟",
      "verse": 9
    },
    {
      "chapter": 16,
      "text_ar": "سيبرق ببروقه، ومن لا يخاف؟ وسيرعد برعوده، ومن لا يرتعد؟",
      "verse": 10
    }
  ]
}
